//msg.payload = Buffer.from([0x55, 0xaa, 0x01, 0xff, 0x00, 0x00, 0xff])
//msg.payload = Buffer.from([0xdd, 0xa5, 0x03, 0x00, 0xff, 0xfd , 0x77])

// JKBMS Dump all registers:
// 4E 57 00 13 00 00 00 00 06 03 00 00 00 00 00 00 68 00 00 01 29
msg = {
    payload: Buffer.from([0x4E, 0x57, 0x00, 0x13, 0x00, 0x00, 0x00, 0x00, 0x06, 0x03, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x68, 0x00, 0x00, 0x01, 0x29]),
    timeout: 10000
}

return msg;

function chksum(buffer, len) {
    var checksum = 0;
    for (let ii = 0; ii < len; ii++) {
        checksum = checksum + buffer[ii];
    }
    return checksum;
}

const buffer = msg.payload;

const jk_get_16bit = (i) => {
    return (buffer[i] << 8) | buffer[i + 1];
};

const jk_get_32bit = (i) => {
    return ((jk_get_16bit(i) << 16) | jk_get_16bit(i + 2)) >>> 0;
};

function format_total_runtime(value) {
    let seconds = value >>> 0; // fuerza uint32

    const years = Math.floor(seconds / (24 * 3600 * 365));
    seconds = seconds % (24 * 3600 * 365);

    const days = Math.floor(seconds / (24 * 3600));
    seconds = seconds % (24 * 3600);

    const hours = Math.floor(seconds / 3600);

    return (years ? years + "y " : "") +
        (days ? days + "d " : "") +
        (hours ? hours + "h" : "");
}

if (buffer[0] != 0x4E || buffer[1] != 0x57)
    node.warn('Invalid header')

msg.jkbms = {};
msg.jkbms.data_len = buffer[2] << 8 | buffer[2 + 1] << 0;
// msg.jkbms.function = buffer[8];
msg.jkbms.computed_crc = chksum(buffer, msg.jkbms.data_len);
msg.jkbms.remote_crc = buffer[msg.jkbms.data_len] << 8 | buffer[msg.jkbms.data_len + 1] << 0;

if (msg.jkbms.computed_crc != msg.jkbms.remote_crc)
    node.warn('JkModbus CRC Check failed!');

var output = {
    Serial: "",
    Dc: {
        Power: null,
        Voltage: null,
        Current: null,
        Temperature: null,
    },
    InstalledCapacity: null,
    RemainingCapacity: null,
    Capacity: null,
    ConsumedAmphours: null,
    Soc: null,
    TimeToGo: null,
    Balancing: 0,
    Alarms: {},
    Info: {},
    History: {},
    System: {
        NrOfCellsPerBattery: 0,
        MinCellVoltage: 100.0,
        MinVoltageCellId: "",
        MaxCellVoltage: -100.0,
        MaxVoltageCellId: "",
        AverageCellVoltage: 0.0
    },
    Voltages: {},
    Balances: {},
    Io: {}
};

// Status request
// -> 0x4E 0x57 0x00 0x13 0x00 0x00 0x00 0x00 0x06 0x03 0x00 0x00 0x00 0x00 0x00 0x00 0x68 0x00 0x00 0x01 0x29
//
// Status response
// <- 0x4E 0x57 0x01 0x1B 0x00 0x00 0x00 0x00 0x06 0x00 0x01: Header
//
// *Data*
//
// Address Content: Description      Decoded content                         Coeff./Unit
// 0x79: Individual Cell voltage
// 0x2A: Cell count               42 / 3 bytes = 14 cells
// 0x01 0x0E 0xED: Cell 1         3821 * 0.001 = 3.821V                        0.001 V
// 0x02 0x0E 0xFA: Cell 2         3834 * 0.001 = 3.834V                        0.001 V
// 0x03 0x0E 0xF7: Cell 3         3831 * 0.001 = 3.831V                        0.001 V
// 0x04 0x0E 0xEC: Cell 4         ...                                          0.001 V
// 0x05 0x0E 0xF8: Cell 5         ...                                          0.001 V
// 0x06 0x0E 0xFA: Cell 6         ...                                          0.001 V
// 0x07 0x0E 0xF1: Cell 7         ...                                          0.001 V
// 0x08 0x0E 0xF8: Cell 8         ...                                          0.001 V
// 0x09 0x0E 0xE3: Cell 9         ...                                          0.001 V
// 0x0A 0x0E 0xFA: Cell 10        ...                                          0.001 V
// 0x0B 0x0E 0xF1: Cell 11        ...                                          0.001 V
// 0x0C 0x0E 0xFB: Cell 12        ...                                          0.001 V
// 0x0D 0x0E 0xFB: Cell 13        ...                                          0.001 V
// 0x0E 0x0E 0xF2: Cell 14        3826 * 0.001 = 3.826V                        0.001 V

// Cell voltages
let cellbase = 11 + 1;

output.System.NrOfCellsPerBattery = buffer[cellbase] / 3;

for (let cell = 1; cell <= output.System.NrOfCellsPerBattery; cell++) {
    var cellVoltage = (buffer[cellbase + cell * 3 - 1] << 8 | buffer[cellbase + cell * 3] << 0) / 1000;
    output.System.AverageCellVoltage += cellVoltage;

    if (cellVoltage < output.System.MinCellVoltage) {
        output.System.MinCellVoltage = cellVoltage;
        output.System.MinVoltageCellId = "C" + cell;
    }

    if (cellVoltage > output.System.MaxCellVoltage) {
        output.System.MaxCellVoltage = cellVoltage;
        output.System.MaxVoltageCellId = "C" + cell;
    }

    output.Voltages['Cell' + cell] = cellVoltage;
}
output.System.AverageCellVoltage = Math.round((output.System.AverageCellVoltage / output.System.NrOfCellsPerBattery) * 1000) / 1000;
output.System.DiffCellVoltage = Math.round((output.System.MaxCellVoltage - output.System.MinCellVoltage) * 1000) / 1000;


const cellByteCount = 11 + output.System.NrOfCellsPerBattery * 3;
msg.jkbms.cellByteCount = cellByteCount;

// UniqueIdentifier
if (buffer[cellByteCount + 209 - 1] != 0x61)
    node.warn('UniqueIdentifier marker incorrect!');
// msg.payload = buffer.slice(cellByteCount + 209, cellByteCount + 209 + 10);

output.Serial = buffer
    .toString('utf8', cellByteCount + 209, cellByteCount + 209 + 10)
    .replace(/[^\x20-\x7E]/g, '');

const offset = 11 + buffer[11 + 1] + 3;

// 0x80 0x00 0x1D: Read power tube temperature                 29°C                      1.0 °C
// --->  99 = 99°C, 100 = 100°C, 101 = -1°C, 140 = -40°C
const rawMOSTemp = jk_get_16bit(offset + 3 * 0);
output.System.MOSTemperature = rawMOSTemp < 99 ? rawMOSTemp : (100 - rawMOSTemp);

// 0x81 0x00 0x1E: Read the temperature in the battery box     30°C                      1.0 °C
output.System.Temperature1 = Math.round(jk_get_16bit(offset + 3 * 1) * 10) / 10;

// 0x82 0x00 0x1C: Read battery temperature                    28°C                      1.0 °C
output.System.Temperature2 = Math.round(jk_get_16bit(offset + 3 * 2) * 10) / 10;

// TODO: Get one closest to limits (Ex 0 and 50)
output.Dc.Temperature = output.System.Temperature1;

// 0x83 0x14 0xEF: Total battery voltage                       5359 * 0.01 = 53.59V      0.01 V
output.Dc.Voltage = jk_get_16bit(offset + 3 * 3) * 0.01;

// 0x84 0x80 0xD0: Current data                                32976                     0.01 A
var rawCurrent = jk_get_16bit(offset + 3 * 4);
let CURRENT_ZERO_CONSTANT = 32768
if (rawCurrent < CURRENT_ZERO_CONSTANT)
    output.Dc.Current = rawCurrent / -100;
else
    output.Dc.Current = (rawCurrent - CURRENT_ZERO_CONSTANT) / 100;

// Power
output.Dc.Power = output.Dc.Current * output.Dc.Voltage;

// 0x85 0x0F: Battery remaining capacity                       15 %
output.Soc = buffer[offset + 3 * 5];

// 0x86 0x02: Number of battery temperature sensors             2                        1.0  count
msg.jkbms.numberOfNTC = buffer[offset + 2 + 3 * 5];

// 0x87 0x00 0x04: Number of battery cycles                     4                        1.0  count
output.History.ChargeCycles = jk_get_16bit(offset + 4 + 3 * 5);

// 0x89 0x00 0x00 0x00 0x00: Total battery cycle capacity
output.Info.TotalChargingCycleCapacity = jk_get_32bit(offset + 4 + 3 * 6);

// 0x8A 0x00 0x0E: Total number of battery strings             14                        1.0  count
msg.jkbms.numberOfStrings = jk_get_16bit(offset + 6 + 3 * 7);


// 0x8B 0x00 0x00: Battery warning message                     0000 0000 0000 0000
//
// Bit 0    Low capacity                                1 (alarm), 0 (normal)    warning
// Bit 1    Power tube overtemperature                  1 (alarm), 0 (normal)    alarm
// Bit 2    Charging overvoltage                        1 (alarm), 0 (normal)    alarm
// Bit 3    Discharging undervoltage                    1 (alarm), 0 (normal)    alarm
// Bit 4    Battery over temperature                    1 (alarm), 0 (normal)    alarm
// Bit 5    Charging overcurrent                        1 (alarm), 0 (normal)    alarm
// Bit 6    Discharging overcurrent                     1 (alarm), 0 (normal)    alarm
// Bit 7    Cell pressure difference                    1 (alarm), 0 (normal)    alarm
// Bit 8    Overtemperature alarm in the battery box    1 (alarm), 0 (normal)    alarm
// Bit 9    Battery low temperature                     1 (alarm), 0 (normal)    alarm
// Bit 10   Cell overvoltage                            1 (alarm), 0 (normal)    alarm
// Bit 11   Cell undervoltage                           1 (alarm), 0 (normal)    alarm
// Bit 12   309_A protection                            1 (alarm), 0 (normal)    alarm
// Bit 13   309_A protection                            1 (alarm), 0 (normal)    alarm
// Bit 14   Reserved
// Bit 15   Reserved
//
// Examples:
// 0x0001 = 00000000 00000001: Low capacity alarm
// 0x0002 = 00000000 00000010: MOS tube over-temperature alarm
// 0x0003 = 00000000 00000011: Low capacity alarm AND power tube over-temperature alarm
msg.jkbms.batteryWarning = jk_get_16bit(offset + 6 + 3 * 8);


const lowCapacity = 0x0000000000000001; // Bit 0: Low capacity alarm: 1 warning only, 0 nomal -> OK
const powerTubeOvertemperature = 0x0000000000000010; // Bit 1: MOS tube overtemperature alarm: 1 alarm, 0 nomal -> OK
const chargingOvervoltage = 0x0000000000000100; // Bit 2: Charge over voltage alarm: 1 alarm, 0 nomal -> OK
const dischargingUndervoltage = 0x0000000000001000; // Bit 3: Discharge undervoltage alarm: 1 alarm, 0 nomal -> OK
const batteryOverTemperature = 0x0000000000010000; // Bit 4: Battery overtemperature alarm: 1 alarm, 0 nomal -> OK
const chargingOvercurrent = 0x0000000000100000; // Bit 5: Charge overcurrent alarm: 1 alarm, 0 nomal -> OK
const dischargingOvercurrent = 0x0000000001000000; // Bit 6: discharge over current alarm: 1 alarm, 0 nomal -> OK
const cellPressureDifference = 0x0000000010000000; // Bit 7: core differential pressure alarm: 1 alarm, 0 nomal -> OK
const overtemperatureAlarmInTheBatteryBox = 0x0000000100000000; // Bit 8: overtemperature alarm in the battery box: 1 alarm, 0 nomal -> OK
const batteryLowTemperature = 0x0000001000000000; // Bit 9: Battery low temperature alarm: 1 alarm, 0 nomal -> OK
const cellOvervoltage = 0x0000010000000000; // Bit 10: Unit overvoltage: 1 alarm, 0 nomal -> OK
const cellUndervoltage = 0x0000100000000000; // Bit 11: Unit undervoltage: 1 alarm, 0 nomal -> OK
const alarm309_AProtection = 0x0001000000000000; // Bit 12:309_A protection: 1 alarm, 0 nomal
const alarm309_BProtection = 0x0010000000000000; // Bit 13:309_B protection: 1 alarm, 0 nomal

output.Alarms.LowSoc = msg.jkbms.batteryWarning & lowCapacity;
output.Alarms.HighInternalTemperature = msg.jkbms.batteryWarning & powerTubeOvertemperature;
output.Alarms.HighVoltage = msg.jkbms.batteryWarning & chargingOvervoltage;
output.Alarms.LowVoltage = msg.jkbms.batteryWarning & dischargingUndervoltage;
output.Alarms.HighTemperature = (msg.jkbms.batteryWarning & batteryOverTemperature) || (msg.jkbms.batteryWarning & overtemperatureAlarmInTheBatteryBox);
output.Alarms.HighChargeCurrent = msg.jkbms.batteryWarning & chargingOvercurrent;
output.Alarms.HighDischargeCurrent = msg.jkbms.batteryWarning & dischargingOvercurrent;
output.Alarms.CellImbalance = msg.jkbms.batteryWarning & cellPressureDifference;
// output.Alarms.OvertemperatureAlarmInTheBatteryBox = msg.jkbms.batteryWarning & overtemperatureAlarmInTheBatteryBox;
output.Alarms.LowTemperature = msg.jkbms.batteryWarning & batteryLowTemperature;
output.Alarms.HighCellVoltage = msg.jkbms.batteryWarning & cellOvervoltage;
output.Alarms.LowCellVoltage = msg.jkbms.batteryWarning & cellUndervoltage;
output.Alarms.alarm309_AProtection = msg.jkbms.batteryWarning & alarm309_AProtection;
output.Alarms.alarm309_BProtection = msg.jkbms.batteryWarning & alarm309_BProtection;


// 0x8C 0x00 0x07: Battery status information                  0000 0000 0000 0111
// Bit 0: Charging enabled        1 (on), 0 (off)
// Bit 1: Discharging enabled     1 (on), 0 (off)
// Bit 2: Balancer enabled        1 (on), 0 (off)
// Bit 3: Battery dropped(?)      1 (normal), 0 (offline)
// Bit 4...15: Reserved

// Example: 0000 0000 0000 0111 -> Charging + Discharging + Balancer enabled
msg.jkbms.batteryStatus = jk_get_16bit(offset + 6 + 3 * 9);

const chargingEnabled = 0b0000000000000001;
const dischargingEnabled = 0b0000000000000010;
const balancingEnabled = 0b0000000000000100;
const batteryConnected = 0b0000000000001000;

output.Io.AllowToCharge = msg.jkbms.batteryStatus & chargingEnabled ? 1 : 0;
output.Io.AllowToDischarge = msg.jkbms.batteryStatus & dischargingEnabled ? 1 : 0;
output.Io.AllowToBalance = msg.jkbms.batteryStatus & balancingEnabled ? 1 : 0;
output.Io.ExternalRelay = msg.jkbms.batteryStatus & batteryConnected ? 1 : 0;


//////////////////////////////////////////////////////////////////////////////////
// CONFIGURATION SECTION

// 0x8E 0x16 0x26: Total voltage overvoltage protection        5670 * 0.01 = 56.70V     0.01 V
output.Info.TotalVoltageOvervoltageProtection = jk_get_16bit(offset + 6 + 3 * 10) * 0.01;

// 0x8F 0x10 0xAE: Total voltage undervoltage protection       4270 * 0.01 = 42.70V     0.01 V
output.Info.TotalVoltageUndervoltageProtection = jk_get_16bit(offset + 6 + 3 * 11) * 0.01;

// 0x90 0x0F 0xD2: Cell overvoltage protection voltage         4050 * 0.001 = 4.050V     0.001 V
output.Info.CellVoltageOvervoltageProtection = jk_get_16bit(offset + 6 + 3 * 12) * 0.001;

// 0x91 0x0F 0xA0: Cell overvoltage recovery voltage           4000 * 0.001 = 4.000V     0.001 V
output.Info.CellVoltageOvervoltageRecovery = jk_get_16bit(offset + 6 + 3 * 13) * 0.001;

// 0x92 0x00 0x05: Cell overvoltage protection delay            5s                         1.0 s
output.Info.CellVoltageOvervoltageDelay = jk_get_16bit(offset + 6 + 3 * 14);

// 0x93 0x0B 0xEA: Cell undervoltage protection voltage        3050 * 0.001 = 3.050V     0.001 V
output.Info.CellVoltageUndervoltageProtection = jk_get_16bit(offset + 6 + 3 * 15) * 0.001;

// 0x94 0x0C 0x1C: Cell undervoltage recovery voltage          3100 * 0.001 = 3.100V     0.001 V
output.Info.CellVoltageUndervoltageRecovery = jk_get_16bit(offset + 6 + 3 * 16) * 0.001;

// 0x95 0x00 0x05: Cell undervoltage protection delay           5s                         1.0 s
output.Info.CellVoltageUndervoltageDelay = jk_get_16bit(offset + 6 + 3 * 17);

// 0x96 0x01 0x2C: Cell pressure difference protection value    300 * 0.001 = 0.300V     0.001 V     0.000-1.000V
output.Info.CellPressureDifferenceProtection = jk_get_16bit(offset + 6 + 3 * 18) * 0.001;

// 0x97 0x00 0x07: Discharge overcurrent protection value       7A                         1.0 A
output.Info.DischargingOvercurrentProtection = output.Info.MaxDischargeCurrent = jk_get_16bit(offset + 6 + 3 * 19);

// 0x98 0x00 0x03: Discharge overcurrent delay                  3s                         1.0 s
output.Info.DischargingOvercurrentDelay = jk_get_16bit(offset + 6 + 3 * 20);

// 0x99 0x00 0x05: Charging overcurrent protection value        5A                         1.0 A
output.Info.ChargingOvercurrentProtection = output.Info.MaxChargeCurrent = jk_get_16bit(offset + 6 + 3 * 21);

// 0x9A 0x00 0x05: Charge overcurrent delay                     5s                         1.0 s
output.Info.ChargingOvercurrentDelay = jk_get_16bit(offset + 6 + 3 * 22);

// 0x9B 0x0C 0xE4: Balanced starting voltage                   3300 * 0.001 = 3.300V     0.001 V
output.Info.BalanceStartingVoltage = jk_get_16bit(offset + 6 + 3 * 23) * 0.001;

// 0x9C 0x00 0x08: Balanced opening pressure difference           8 * 0.001 = 0.008V     0.001 V     0.01-1V
output.Info.BalanceOpeningPressureDifference = jk_get_16bit(offset + 6 + 3 * 24) * 0.001;

// 0x9D 0x01: Active balance switch                              1 (on)                     Bool     0 (off), 1 (on)
// output.Info.BalancingSwitch_binary = buffer[offset2 + 6 + 3 * 25];
output.Info.BalancerSwitch = buffer[offset + 6 + 3 * 25];

// 0x9E 0x00 0x5A: Power tube temperature protection value                90°C            1.0 °C     0-100°C
output.Info.PowerTubeTemperatureProtection = jk_get_16bit(offset + 8 + 3 * 25);

// 0x9F 0x00 0x46: Power tube temperature recovery value                  70°C            1.0 °C     0-100°C
output.Info.PowerTubeTemperatureRecovery = jk_get_16bit(offset + 8 + 3 * 26);

// 0xA0 0x00 0x64: Temperature protection value in the battery box       100°C            1.0 °C     40-100°C
output.Info.TemperatureProtection = jk_get_16bit(offset + 8 + 3 * 27);

// 0xA1 0x00 0x64: Temperature recovery value in the battery box         100°C            1.0 °C     40-100°C
output.Info.TemperatureRecovery = jk_get_16bit(offset + 8 + 3 * 28);

// 0xA2 0x00 0x14: Battery temperature difference protection value        20°C            1.0 °C     5-10°C
output.Info.TemperatureDifferenceProtection = jk_get_16bit(offset + 8 + 3 * 29);

// 0xA3 0x00 0x46: Battery charging high temperature protection value     70°C            1.0 °C     0-100°C
output.Info.ChargingHighTemperatureProtection = jk_get_16bit(offset + 8 + 3 * 30);

// 0xA4 0x00 0x46: Battery discharge high temperature protection value    70°C            1.0 °C     0-100°C
output.Info.DischargingHighTemperatureProtection = jk_get_16bit(offset + 8 + 3 * 31);

// 0xA5 0xFF 0xEC: Charging low temperature protection value             -20°C            1.0 °C     -45...25°C
output.Info.ChargingLowTemperatureProtection = jk_get_16bit(offset + 8 + 3 * 32);

// 0xA6 0xFF 0xF6: Charging low temperature protection recovery value    -10°C            1.0 °C     -45...25°C
output.Info.ChargingLowTemperatureRecovery = jk_get_16bit(offset + 8 + 3 * 33);

// 0xA7 0xFF 0xEC: Discharge low temperature protection value            -20°C            1.0 °C     -45...25°C
output.Info.DischargingLowTemperatureProtection = jk_get_16bit(offset + 8 + 3 * 34);

// 0xA8 0xFF 0xF6: Discharge low temperature protection recovery value   -10°C            1.0 °C     -45...25°C
output.Info.DischargingLowTemperatureRecovery = jk_get_16bit(offset + 8 + 3 * 35);

//////////////////////////////////////////////////////////////////////////////////

// 0xA9 0x0E: Battery string setting                                      14              1.0 count
// this->publish_state_(this->battery_string_setting_sensor_, (float) data[offset + 8 + 3 * 36]);

// 0xAA 0x00 0x00 0x02 0x30: Total battery capacity setting              560 Ah           1.0 Ah
output.InstalledCapacity = jk_get_32bit(offset + 10 + 3 * 36);
output.RemainingCapacity = output.Capacity = Math.round((output.InstalledCapacity * (output.Soc * 0.01)) * 10) / 10;
output.ConsumedAmphours = Math.round((output.InstalledCapacity - output.RemainingCapacity) * 10) / 10;

// TimeToGo (only charging)
var percent_per_seconds = Math.abs(output.Dc.Current / (output.InstalledCapacity / 100)) / 3600;
const soc_diff = 100 - output.Soc;
var seconds_to_go = soc_diff / percent_per_seconds;
output.TimeToGo = seconds_to_go != null && output.Dc.Current > 0.1 ? seconds_to_go : null;

// Max Battery Voltage
//TODO: Calculate battery.py:558

// 0xAB 0x01: Charging MOS tube switch                                     1 (on)         Bool       0 (off), 1 (on)
// this -> publish_state_(this -> charging_switch_binary_sensor_, (bool) buffer[offset2 + 15 + 3 * 36]);
output.Info.ChargingSwitch = buffer[offset + 15 + 3 * 36];

// 0xAC 0x01: Discharge MOS tube switch                                    1 (on)         Bool       0 (off), 1 (on)
// this -> publish_state_(this -> discharging_switch_binary_sensor_, (bool) buffer[offset2 + 17 + 3 * 36]);
output.Info.DischargingSwitch = buffer[offset + 17 + 3 * 36];

// 0xAD 0x04 0x11: Current calibration                       1041mA * 0.001 = 1.041A     0.001 A     0.1-2.0A
output.Info.CurrentCalibration = jk_get_16bit(offset + 19 + 3 * 36) * 0.001;

// 0xAE 0x01: Protection board address                                     1              1.0
output.Info.DeviceAddress = buffer[offset + 19 + 3 * 37];

// 0xAF 0x01: Battery Type                                                 1              1.0
const BATTERY_TYPES = [
    "Lithium Iron Phosphate", // 0x00
    "Ternary Lithium",        // 0x01
    "Lithium Titanate",       // 0x02
];
const BATTERY_TYPES_SIZE = BATTERY_TYPES.length;

// ---> 0 (lithium iron phosphate), 1 (ternary), 2 (lithium titanate)
var rawBatteryType = buffer[offset + 21 + 3 * 37];
if (rawBatteryType < BATTERY_TYPES_SIZE) {
    output.Info.BatteryType = BATTERY_TYPES[rawBatteryType];
} else {
    output.Info.BatteryType = "Unknown";
}


// 0xB0 0x00 0x0A: Sleep waiting time                                      10s            1.0 s
output.Info.SleepWaitTime = jk_get_16bit(offset + 23 + 3 * 37);

// 0xB1 0x14: Low volume alarm                                             20%            1.0 %      0-80%
output.Info.AlarmLowVolume = buffer[offset + 23 + 3 * 38];

// 0xB2 0x31 0x32 0x33 0x34 0x35 0x36 0x00 0x00 0x00 0x00: Modify parameter password
// output.Info.Password = new TextDecoder().decode(buffer.slice(start, end));
// output.Info.Password = buffer.substring(start, end);
output.Info.Password = buffer.toString('utf8', offset + 25 + 3 * 38, offset + 35 + 3 * 38);

// 0xB3 0x00: Dedicated charger switch                                     1 (on)         Bool       0 (off), 1 (on)
output.Info.DedicatedChargerSwitch = buffer[offset + 36 + 3 * 38];

// 0xB4 0x49 0x6E 0x70 0x75 0x74 0x20 0x55 0x73: Device ID code
output.Info.DeviceType = buffer.toString('utf8', offset + 38 + 3 * 38, offset + 46 + 3 * 38);

// 0xB5 0x32 0x31 0x30 0x31: Date of manufacture
// 0xB6 0x00 0x00 0xE2 0x00: System working hours
output.Info.TotalRuntime = jk_get_32bit(offset + 46 + 3 * 40) * 0.0166666666667;
output.Info.TotalRuntimeFormatted = format_total_runtime(jk_get_32bit(offset + 46 + 3 * 40) * 60);

// 0xB7 0x48 0x36 0x2E 0x58 0x5F 0x5F 0x53
//      0x36 0x2E 0x31 0x2E 0x33 0x53 0x5F 0x5F: Software version number
output.Info.SoftwareVersion = buffer.toString('utf8', offset + 51 + 3 * 40, offset + 51 + 3 * 45);

// 0xB8 0x00: Whether to start current calibration
// 0xB9 0x00 0x00 0x00 0x00: Actual battery capacity
//   Firmware version >= 10.10 required
//   See https://github.com/syssi/esphome-jk-bms/issues/212 for details
output.Info.ActualBatteryCapacity = jk_get_32bit(offset + 54 + 3 * 45);

// 0xBA 0x42 0x54 0x33 0x30 0x37 0x32 0x30 0x32 0x30 0x31 0x32 0x30
//      0x30 0x30 0x30 0x32 0x30 0x30 0x35 0x32 0x31 0x30 0x30 0x31: Manufacturer ID naming
output.Info.Manufacturer = buffer.toString('utf8', offset + 59 + 3 * 45, offset + 83 + 3 * 45);

// 0xC0 0x01: Protocol version number
output.Info.ProtocolVersion = buffer[offset + 84 + 3 * 45];

// 00 00 00 00 68 00 00 54 D1: End of frame

// Cell balancing
for (let [k] of Object.entries(output.Voltages)) {
    // node.warn({k, v});
    let cellId = k.replace("Cell", "C");
    output.Balances[k] = (output.Io.AllowToBalance && (cellId == output.System.MinVoltageCellId || cellId == output.System.MaxVoltageCellId)) ? 1 : 0;
    if (output.Balances[k] && !output.Balancing) output.Balancing == 1;
}

// msg.output = output;

let devices = flow.get("devices") ?? {};
devices[output.Serial] = output;
flow.set("devices", devices);

node.status({ fill: "green", shape: "ring", text: output.Serial });

return { topic: "bms/" + output.Serial, payload: output };
